select jsonb_build_object('columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'required',a.attnotnull,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) order by c.relname,a.attnum) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='public' and c.relname in ('procurement_sources','procurement_leads','procurement_intake_items','procurement_intake_leads','procurement_request_leads','procurement_search_requests','procurement_versions','procurement_events') and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('procurement_sources','procurement_leads','procurement_intake_items','procurement_intake_leads','procurement_request_leads','procurement_search_requests','procurement_versions','procurement_events')),'functions',(select jsonb_agg(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('procurement_lead_changed','procurement_sync_lead_columns','procurement_parse_date','procurement_parse_deadline')),'triggers',(select jsonb_agg(pg_get_triggerdef(t.oid)) from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relname in ('procurement_sources','procurement_leads','procurement_intake_items','procurement_intake_leads','procurement_request_leads','procurement_search_requests','procurement_versions','procurement_events'))) as schema;